// ---------------------------------------------------------------------------
// UC1-S5/S6 — "Drop rejected — out of bounds"
// WHEN widget cells would be outside grid boundary
// THEN drop rejected
// ---------------------------------------------------------------------------
describe('PBT UC1-S6: out-of-bounds placement always rejected', () => {
  it('UC1-S6: isValidPlacement always false when x+w > cols', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 4 }),
        fc.integer({ min: 1, max: 4 }),
        (cols, rows, w, h) => {
          const candidate: WidgetLayout = { id: 'c', x: cols, y: 0, w, h }; // x == cols → always OOB
          return !isValidPlacement([], candidate, cols, rows);
        }
      )
    );
  });

  it('UC1-S6: isValidPlacement always false when y+h > rows', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 4 }),
        fc.integer({ min: 1, max: 4 }),
        (cols, rows, w, h) => {
          const candidate: WidgetLayout = { id: 'c', x: 0, y: rows, w, h }; // y == rows → always OOB
          return !isValidPlacement([], candidate, cols, rows);
        }
      )
    );
  });
});

// ---------------------------------------------------------------------------
// UC1-S7/S8 — "Layout state updated on valid drop"
// WHEN valid drop completed
// THEN layout entry updated to new x,y; all others unchanged
// (Property: isValidPlacement is idempotent for same position)
// ---------------------------------------------------------------------------
describe('PBT UC1-S7: valid placement is idempotent (same position accepted repeatedly)', () => {
  it('UC1-S7: placing a widget twice at same position is always valid (self-exclusion)', () => {
    fc.assert(
      fc.property(
        widgetArb(8, 8),
        fc.integer({ min: 8, max: 12 }),
        fc.integer({ min: 8, max: 12 }),
        (widget, cols, rows) => {
          const safe: WidgetLayout = {
            ...widget,
            x: Math.min(widget.x, cols - widget.w),
            y: Math.min(widget.y, rows - widget.h),
          };
          const layout = [safe];
          // Placing same widget at same position — valid (self-excluded)
          return isValidPlacement(layout, safe, cols, rows);
        }
      )
    );
  });
});

// ---------------------------------------------------------------------------
// UC1-S7/S8 — "Widget rendered at new position after drop"
// WHEN layout state updated after valid drop
// THEN widget rendered at new grid position
// (Property: buildOccupancySet reflects new position immediately)
// ---------------------------------------------------------------------------
describe('PBT UC1-S8: updated layout position reflects in occupancy set', () => {
  it('UC1-S8: after moving widget, new cells are occupied and old cells are free', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 4, max: 10 }),
        fc.integer({ min: 4, max: 10 }),
        (cols, rows) => {
          const before: WidgetLayout = { id: 'a', x: 0, y: 0, w: 1, h: 1 };
          const after: WidgetLayout = { id: 'a', x: cols - 1, y: rows - 1, w: 1, h: 1 };
          const oldSet = buildOccupancySet([before]);
          const newSet = buildOccupancySet([after]);
          return (
            oldSet.has('0,0') &&
            !newSet.has('0,0') &&
            newSet.has(`${cols - 1},${rows - 1}`)
          );
        }
      )
    );
  });
});

