// ---------------------------------------------------------------------------
// UC1-E6a3 — "Layout state unchanged after rejected drop"
// WHEN drop rejected
// THEN layout array reference is unchanged
// (Property: isValidPlacement=false means caller must not update state)
// ---------------------------------------------------------------------------
describe('PBT UC1-E6a3: rejected placement never mutates the layout array', () => {
  it('UC1-E6a3: buildOccupancySet is a pure function — same input always gives same output', () => {
    fc.assert(
      fc.property(
        fc.array(widgetArb(8, 8), { minLength: 0, maxLength: 5 }),
        (widgets) => {
          const set1 = buildOccupancySet(widgets);
          const set2 = buildOccupancySet(widgets);
          if (set1.size !== set2.size) return false;
          for (const key of set1) {
            if (!set2.has(key)) return false;
          }
          return true;
        }
      )
    );
  });
});

// ---------------------------------------------------------------------------
// UC1-E6b/E6b1 — "Widget returns to origin on out-of-bounds placement"
// WHEN target cells partially outside grid bounds
// THEN treated as invalid
// ---------------------------------------------------------------------------
describe('PBT UC1-E6b: out-of-bounds candidate always invalid', () => {
  it('UC1-E6b: isValidPlacement false for any widget exceeding grid on any side', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 8 }),
        fc.integer({ min: 1, max: 4 }),
        fc.integer({ min: 1, max: 4 }),
        fc.integer({ min: 0, max: 3 }),
        (cols, rows, w, h, extra) => {
          // Exceed right boundary
          const overRight: WidgetLayout = { id: 'r', x: cols - w + 1 + extra, y: 0, w, h };
          // Exceed bottom boundary
          const overBottom: WidgetLayout = { id: 'b', x: 0, y: rows - h + 1 + extra, w, h };
          return (
            !isValidPlacement([], overRight, cols, rows) &&
            !isValidPlacement([], overBottom, cols, rows)
          );
        }
      )
    );
  });
});
